/* ==========================================================================
   THE PAINTED TITLE. The title screen shows a painted logo (assets/ui/title_logo.webp, cut by tools/ingest_title.py from a Gemini picture on
   flat magenta): "Below the" and "bbey" in carved sandstone blackletter, and a large illuminated A in gold leaf, lapis and vermilion that is the
   drop cap of "Abbey". It replaces the title that used to be drawn in code (a blackletter "Below the" and a small red square with a gilded A).
   The old drawing stays as the fallback until the picture has loaded: drawTitle is wrapped, the old function still draws the veil, the
   tagline and the buttons, and only its title strokes (the three title strings and the red initial frame) are switched off for that call.
   A slow golden glint crosses the A every few seconds and the little lit window inside it flickers (both cheap: one clipped gradient).
   The #loading screen's title text is swapped for the small copy of the same picture (TL_SMALL, a data: address, so it shows at once and the
   itch.io shim, which holds back assets/ paths, never touches it). The loading bar and the download note are left exactly as they are.
   The two TL_ lines below are rewritten by tools/ingest_title.py. Names start with TL.
   ========================================================================== */
const TL_META={"A":[0.0383,0.0645,0.4251,0.913],"win":[0.2337,0.3833],"aspect":2.3121,"units":[272.25,117.75]};
const TL_SMALL='data:image/webp;base64,';
const TL={img:null,ok:false,failed:false,started:false,pre:null,HB:124,TOP:18,px:0,py:0,pw:0,ph:0,sharp:.7,rad:1.1};
function tlLoad(){
  if(TL.started)return;TL.started=true;
  const im=new Image();im.decoding='async';
  im.onload=()=>{TL.img=im;TL.ok=true};
  im.onerror=()=>{TL.failed=true};
  im.src='assets/ui/title_logo.webp?v='+(typeof VERSION!=='undefined'?VERSION:'1')}
/* a light unsharp mask on the finished cache: the picture is painted soft, and the screen adds bloom and a smooth upscale, so edges are given a little bite back */
function tlSharpen(c,amount,radius){
  try{
    const w=c.width,h=c.height,x=c.getContext('2d'),b=document.createElement('canvas');b.width=w;b.height=h;const bx=b.getContext('2d');
    bx.filter='blur('+radius+'px)';if(bx.filter==='none')return;   // no ctx.filter (Safari): leave the picture as it is
    bx.drawImage(c,0,0);
    const A=x.getImageData(0,0,w,h),B=bx.getImageData(0,0,w,h),a=A.data,bl=B.data;
    for(let i=0;i<a.length;i+=4){if(a[i+3]===0)continue;for(let k=0;k<3;k++){const v=a[i+k]+amount*(a[i+k]-bl[i+k]);a[i+k]=v<0?0:v>255?255:v}}
    x.putImageData(A,0,0)}catch(e){}}
/* the picture reduced to the exact pixel size it is drawn at (the canvas is 2 px per design unit), by halves and then one last draw, high quality,
   and put at whole canvas pixels so no edge falls between two pixels */
function tlPrepare(){
  const im=TL.img,u=TL_META.units||[250,250/(TL_META.aspect||2)],sc=Math.min(1,TL.HB/u[1]);
  const tw=Math.round(u[0]*sc*2),th=Math.round(tw*im.naturalHeight/im.naturalWidth);
  let src=im,w=im.naturalWidth,h=im.naturalHeight;
  while(w/2>tw){const c=document.createElement('canvas');w=Math.round(w/2);h=Math.round(h/2);c.width=w;c.height=h;const x=c.getContext('2d');x.imageSmoothingQuality='high';x.drawImage(src,0,0,w,h);src=c}
  const c=document.createElement('canvas');c.width=tw;c.height=th;const x=c.getContext('2d');x.imageSmoothingQuality='high';
  try{x.filter='saturate(1.05) contrast(1.04) brightness(1.06)'}catch(e){}
  x.drawImage(src,0,0,tw,th);x.filter='none';
  tlSharpen(c,TL.sharp,TL.rad);
  TL.pre=c;TL.pw=tw;TL.ph=th;TL.px=Math.round(420-tw/2);TL.py=Math.round(TL.TOP*2)}
function tlTime(){return performance.now()/1000}
function tlDraw(){
  if(!TL.pre)return;
  const W=TL.pw/2,H=TL.ph/2,x0=TL.px/2,y0=TL.py/2,t=tlTime();
  ctx.save();
  /* a soft dark pool behind the letters so the logo reads on any wall */
  {const g=ctx.createRadialGradient(210,y0+H*.5,10,210,y0+H*.5,W*.62);g.addColorStop(0,'rgba(2,1,0,.5)');g.addColorStop(1,'rgba(2,1,0,0)');
    ctx.fillStyle=g;ctx.save();ctx.translate(210,y0+H*.5);ctx.scale(1,.52);ctx.translate(-210,-(y0+H*.5));ctx.fillRect(210-W*.7,y0-H*.5,W*1.4,H*2);ctx.restore()}
  ctx.drawImage(TL.pre,x0,y0,W,H);
  const A=TL_META.A;
  if(A){
    const px=x0+A[0]*W,py=y0+A[1]*H,pw=(A[2]-A[0])*W,ph=(A[3]-A[1])*H;
    /* the lit window inside the A: a small warm flicker */
    const win=TL_META.win;
    if(win){const wx=x0+win[0]*W,wy=y0+win[1]*H,fl=.5+.5*Math.sin(t*5.1)*Math.sin(t*2.3+1.1);
      const g=ctx.createRadialGradient(wx,wy,0,wx,wy,9);g.addColorStop(0,'rgba(255,190,80,'+(.18+.16*fl).toFixed(3)+')');g.addColorStop(1,'rgba(255,150,40,0)');
      ctx.save();ctx.beginPath();ctx.rect(px,py,pw,ph);ctx.clip();ctx.globalCompositeOperation='lighter';ctx.fillStyle=g;ctx.fillRect(wx-10,wy-10,20,20);ctx.restore()}
    /* the golden glint: a soft slanted band that sweeps across the panel once every nine seconds */
    const P=9,sw=1.5,u=(t%P)/sw;
    if(u<1){
      const e=u*u*(3-2*u),cx=px-pw*.25+e*pw*1.5,cy=py+ph*.5,ang=-.5,bw=pw*.2,nx=Math.cos(ang)*bw,ny=Math.sin(ang)*bw;
      const g=ctx.createLinearGradient(cx-nx,cy-ny,cx+nx,cy+ny);
      const a=.62*Math.sin(Math.PI*u);
      g.addColorStop(0,'rgba(255,226,140,0)');g.addColorStop(.5,'rgba(255,236,170,'+a.toFixed(3)+')');g.addColorStop(1,'rgba(255,226,140,0)');
      ctx.save();ctx.beginPath();ctx.rect(px,py,pw,ph);ctx.clip();ctx.globalCompositeOperation='lighter';ctx.fillStyle=g;ctx.fillRect(px,py,pw,ph);ctx.restore()}
  }
  ctx.restore()}
{const _tlDrawTitle=drawTitle;
  drawTitle=function(){
    if(!TL.ok){tlLoad();return _tlDrawTitle.apply(this,arguments)}
    if(!TL.pre){try{tlPrepare()}catch(e){TL.ok=false;TL.failed=true;return _tlDrawTitle.apply(this,arguments)}}
    /* run the old screen (veil, tagline, buttons) with its own title drawing switched off */
    const fT=ctx.fillText,sT=ctx.strokeText,dIF=drawInitialFrame,skip=s=>s==='Below the'||s==='A'||s==='bbey';
    ctx.fillText=function(s){if(skip(s))return;return fT.apply(this,arguments)};
    ctx.strokeText=function(s){if(skip(s))return;return sT.apply(this,arguments)};
    drawInitialFrame=function(){};
    try{_tlDrawTitle.apply(this,arguments)}
    finally{delete ctx.fillText;delete ctx.strokeText;drawInitialFrame=dIF}
    tlDraw()};
  try{tlLoad()}catch(e){}}
/* the loading screen: the plain text title becomes the painted logo once it has decoded (the bar, the note and the "Loading" line are not touched) */
try{
  const el=document.querySelector('#loading .ld-t');
  if(el&&TL_SMALL&&!el.querySelector('img')){
    const im=new Image();im.alt='Below the Abbey';
    im.style.cssText='display:block;width:min(82vw,420px);height:auto;margin:0 auto;filter:drop-shadow(0 3px 8px rgba(0,0,0,.75))';
    im.onload=()=>{el.textContent='';el.style.fontSize='0';el.appendChild(im)};
    im.src=TL_SMALL}
}catch(e){}
